DEMO_PASSWORD = "demo12345"
LOWER = {"senior": "middle", "middle": "junior", "junior": None}


def reset(db: Session) -> None:
    for table in reversed(Base.metadata.sorted_tables):
        db.execute(table.delete())
    db.commit()


# ------------------------------------------------------------------ FSP registry snapshot

def build_registry(personas: list[Persona], today) -> dict:
    rng = random.Random(99)
    participants = []
    for p in personas:
        if p.fsp_id:
            participants.append({
                "fsp_id": p.fsp_id, "full_name": f"{p.last_name} {p.first_name}", "email": p.email,
                "region": REGIONS.get(p.city), "sport_rank": p.sport_rank,
                "achievements": [a.to_registry() for a in p.achievements],
            })
    for u in UNCLAIMED:
        participants.append({
            "fsp_id": u["fsp_id"], "full_name": u["full_name"], "email": u["email"], "region": u["region"],
            "sport_rank": u["sport_rank"],
            "achievements": [a.to_registry() for a in _achievements(rng, u["spec"], 0.6, 3, today)],
        })
    # participants of FSP events who are not on the platform (realistic registry size)
    for i in range(40):
        first, last = rng.choice(MALE)
        spec = rng.choice(["backend", "frontend", "data_ml", "devops"])
        participants.append({
            "fsp_id": f"FSP-3{i:05d}", "full_name": f"{last} {first}", "email": f"participant{i}@fsp-registry.example",
            "region": rng.choice(list(REGIONS.values())), "sport_rank": rng.choice([None, None, "III разряд"]),
            "achievements": [a.to_registry() for a in _achievements(rng, spec, 0.3, rng.randint(1, 3), today)],
        })
    return {"source": "synthetic snapshot of the FSP registry (hackathon mock)",
            "generated_at": today.isoformat(), "participants": participants}


# ------------------------------------------------------------------ simulated respondent

def simulated_answer(item: TestItem, theta: float, rng: random.Random) -> list:
    ok = rng.random() < p_correct(theta, item.irt_a, item.irt_b, item.irt_c)
    if item.qtype == "numeric":
        v = float(item.correct[0])
        return [v] if ok else [v + rng.choice([-2, -1, 1, 3, 10])]
    if ok:
        return list(item.correct)
    wrong = [i for i in range(len(item.options)) if i not in item.correct]
    if item.qtype == "single":
        return [rng.choice(wrong)]
    picked = set(item.correct)
    if len(picked) > 1 and rng.random() < 0.5:
        picked.discard(rng.choice(sorted(picked)))
    elif wrong:
        picked.add(rng.choice(wrong))
    return sorted(picked)


def take_test(db: Session, c: CandidateProfile, spec: str, grade: str, theta: float, when, rng):
    att = testing.start(db, c, spec, grade, now=when, seed=rng.randrange(2**31))
    for k, item in enumerate(att.items):
        testing.answer(db, c, att.id, item.id, simulated_answer(item, theta, rng),
                       now=when + timedelta(seconds=40 * (k + 1)))
    return testing.finish(db, c, att.id, now=when + timedelta(minutes=14))


# ------------------------------------------------------------------ main

def create_user(db: Session, email: str, role: str, when) -> User:
    u = User(email=email, password_hash=hash_password(DEMO_PASSWORD), role=role, is_email_verified=True,
             created_at=when)
    db.add(u)
    db.flush()
    return u


def seed_candidate(db: Session, p: Persona, skills: dict[str, Skill], now, rng: random.Random) -> CandidateProfile:
    created = now - timedelta(days=p.days_ago + 3)
    u = create_user(db, p.email, Role.CANDIDATE, created)
    c = CandidateProfile(
        user_id=u.id, first_name=p.first_name, last_name=p.last_name, city=p.city, phone=p.phone,
        telegram=p.telegram, headline=p.headline, about=p.about, experience_years=p.experience_years,
        expected_salary=p.expected_salary, work_format=p.work_format, specialization_id=p.specialization,
        declared_grade_id=p.declared_grade, consent_processing_at=created, consent_publication_at=created,
        open_to_offers=p.open_to_offers, created_at=created, last_active_at=now - timedelta(days=p.days_ago),
        team_roles=["Разработчик"] if p.grade != "senior" else ["Тимлид", "Архитектор"],
        soft_skills=rng.sample(["Коммуникабельность", "Ответственность", "Менторство", "Самостоятельность",
                                "Работа в команде", "Системное мышление"], 3),
        education=rng.choice(["МГТУ им. Баумана", "ИТМО", "НГУ", "КФУ", "УрФУ", "ТПУ", "ВШЭ", "МФТИ"]),
    )
    db.add(c)
    db.flush()
    for slug, level in p.skills.items():
        c.skills.append(CandidateSkill(skill_id=skills[slug].id, level=level,
                                       years=round(min(p.experience_years, 1 + level * 0.8), 1)))
    db.flush()
    db.refresh(c)
    fsp_service.try_auto_link(db, c)  # same code path as e-mail verification
    db.commit()
    return c


def run(db: Session, *, wipe: bool = False) -> dict:
    if wipe:
        reset(db)
    seed_reference(db)
    now = utcnow()
    today = now.date()
    rng = random.Random(42)

    personas = demo_personas(today) + build_personas(today)
    DATA_FILE.parent.mkdir(parents=True, exist_ok=True)
    DATA_FILE.write_text(json.dumps(build_registry(personas, today), ensure_ascii=False, indent=1), encoding="utf-8")
    get_mock_registry.cache_clear()

    skills = {s.slug: s for s in db.scalars(select(Skill))}
    cands: dict[str, CandidateProfile] = {}
    for p in personas:
        c = seed_candidate(db, p, skills, now, rng)
        cands[p.key] = c
        if not p.take_test:
            continue
        when = now - timedelta(days=p.days_ago)
        if p.key == "demo_candidate":
            # the showcase profile must be a confident Backend · Middle: replay until it passes
            for attempt_seed in range(50):
                res = take_test(db, c, p.specialization, p.declared_grade, p.theta, when,
                                random.Random(attempt_seed))
                if res.passed:
                    break
                db.delete(db.get(TestAttempt, res.attempt_id))  # failed replay leaves no trace
                db.commit()
            db.commit()
            continue
        res = take_test(db, c, p.specialization, p.declared_grade, p.theta, when, rng)
        if res.outcome == "needs_confirmation":
            # production policy: one confirmation form, available immediately
            res = take_test(db, c, p.specialization, p.declared_grade, p.theta, when + timedelta(minutes=20), rng)
        lower = LOWER[p.declared_grade]
        if not res.passed and lower:
            # the grade is never lowered forcibly: the candidate chooses to take a lower-grade test
            res = take_test(db, c, p.specialization, lower, p.theta, when + timedelta(minutes=30), rng)
        db.commit()

    employers: dict[str, EmployerProfile] = {}
    for co in COMPANIES:
        u = create_user(db, co["email"], Role.EMPLOYER, now - timedelta(days=60))
        e = EmployerProfile(user_id=u.id, contact_email=co["email"],
                            **{k: v for k, v in co.items() if k not in ("key", "email")})
        db.add(e)
        db.flush()
        employers[co["key"]] = e
    db.commit()

    jobs: list[Job] = []
    for n in NEEDS:
        e = employers[n["company"]]
        job = employer_service.create_job(db, e, {
            "title": n["title"], "description": n["description"], "team_description": n["team"],
            "specialization_id": n["specialization_id"], "grade_id": n["grade_id"], "must_skills": n["must"],
            "nice_skills": n["nice"], "salary_from": n["salary"][0], "salary_to": n["salary"][1],
            "work_format": n["work_format"], "city": n["city"], "min_experience_years": n["exp"],
            "weights_preset": "balanced", "is_public": n["public"],
        })
        jobs.append(job)

    star = cands["demo_candidate"]
    demo_emp = employers["demo_employer"]
    _invite(db, demo_emp, star, jobs[0], InvitationStatus.SENT, now - timedelta(hours=20), rng,
            title="Python Backend Developer", contact="Telegram @future_tech_hr или +7 495 000-11-22")
    _invite(db, employers["emp2"], star, None, InvitationStatus.VIEWED, now - timedelta(days=3), rng,
            title="Backend-разработчик (Python), команда платежей",
            contact="hr@severcode.example, Павел", salary=(210_000, 260_000))
    _invite(db, employers["emp5"], star, None, InvitationStatus.REJECTED, now - timedelta(days=40), rng,
            title="Backend-разработчик рекомендательного API", contact="@media_hr", salary=(160_000, 190_000))

    statuses = [InvitationStatus.SENT, InvitationStatus.VIEWED, InvitationStatus.ACCEPTED, InvitationStatus.REJECTED,
                InvitationStatus.ACCEPTED, InvitationStatus.EXPIRED]
    for job in jobs:
        rows = list(db.scalars(select(MatchResult).where(MatchResult.job_id == job.id).order_by(MatchResult.rank)))
        for k, row in enumerate(rows[1:4]):
            if row.candidate_id in (star.id, cands["demo_fresh"].id):
                continue
            status = statuses[(job.id + k) % len(statuses)]
            created = now - timedelta(days=rng.randint(1, 25))
            if status == InvitationStatus.EXPIRED:
                created = now - timedelta(days=30)
            _invite(db, job.employer, db.get(CandidateProfile, row.candidate_id), job, status, created, rng)
        if job.is_public:
            for row in rows[4:6]:
                c = db.get(CandidateProfile, row.candidate_id)
                if c.id == star.id:
                    continue
                try:
                    jobs_service.apply(db, c, job.id, "Здравствуйте! Мне интересна ваша вакансия, "
                                                      "готов(а) обсудить детали.")
                except Exception:
                    db.rollback()

    for t in TASKS:
        task = ShortTask(employer_id=employers[t["company"]].id, specialization_id=t["spec"], title=t["title"],
                         description=t["description"], created_at=now - timedelta(days=5))
        db.add(task)
        db.flush()
        pool = [c for c in cands.values() if c.verified_specialization_id == t["spec"] and c.id != star.id][:3]
        for c in pool:
            db.add(TaskSubmission(task_id=task.id, candidate_id=c.id, rating=rng.choice([3, 4, 5, None]),
                                  answer="Предлагаю следующий подход: зафиксировать требования, выбрать "
                                         "решение с понятными гарантиями и измерить эффект метриками.",
                                  created_at=now - timedelta(days=rng.randint(1, 4))))
    db.commit()
    for job in jobs:
        matching.run(db, job)

    return {"candidates": len(cands), "employers": len(employers), "jobs": len(jobs),
            "verified": sum(1 for c in cands.values() if c.verified_grade_id),
            "invitations": db.query(Invitation).count(), "applications": db.query(Application).count()}


def _invite(db, employer, candidate, job, status, created, rng, title=None, contact=None, salary=None):
    sal = salary or ((job.salary_from, job.salary_to) if job else (150_000, 220_000))
    try:
        inv = invitation_service.create(
            db, employer, candidate_id=candidate.id, job_id=job.id if job else None,
            position_title=title or (job.title if job else "Разработчик"),
            description=(job.description if job else "Ищем сильного инженера в продуктовую команду.")
            + " Готовы обсудить задачи и формат на коротком созвоне.",
            salary_from=sal[0], salary_to=sal[1], work_format=job.work_format if job else "remote",
            contact_method=contact or f"{employer.contact_telegram} · {employer.contact_email}",
        )
    except Exception:
        db.rollback()
        return None
    inv.created_at = created
    inv.expires_at = created + timedelta(days=14)
    inv.status = status
    if status in (InvitationStatus.VIEWED, InvitationStatus.ACCEPTED, InvitationStatus.REJECTED):
        inv.viewed_at = created + timedelta(hours=rng.randint(1, 20))
    if status in (InvitationStatus.ACCEPTED, InvitationStatus.REJECTED):
        inv.responded_at = inv.viewed_at + timedelta(hours=rng.randint(1, 30))
        inv.candidate_message = ("Спасибо, интересно! Давайте созвонимся." if status == InvitationStatus.ACCEPTED
                                 else "Спасибо, но сейчас рассматриваю другие предложения.")
    if status == InvitationStatus.ACCEPTED:
        from app.services import privacy

        privacy.log_disclosure(db, employer.id, candidate.id, "invitation_accepted")
    db.commit()
    return inv
